<?php
declare(strict_types=1);
namespace App\Application\Taxonomy\Service;
use App\Application\Taxonomy\DTO\Request\CreateTaxonomySubjectRequestDto;use App\Application\Taxonomy\DTO\Response\TaxonomySubjectResponseDto;use App\Application\Taxonomy\Mapper\TaxonomySubjectResponseMapper;use App\Application\Study\Port\TransactionManagerInterface;use App\Domain\Taxonomy\Entity\TaxonomySubject;use App\Domain\Taxonomy\Repository\TaxonomySubjectRepositoryInterface;use App\Domain\Taxonomy\Service\SubjectTaxonomyService;
final class CreateTaxonomySubjectService { public function __construct(private readonly TaxonomySubjectRepositoryInterface $subjects,private readonly SubjectTaxonomyService $taxonomy,private readonly TaxonomySubjectResponseMapper $mapper,private readonly TransactionManagerInterface $transactions){} public function create(CreateTaxonomySubjectRequestDto $input):TaxonomySubjectResponseDto{return $this->transactions->transactional(function()use($input){$name=trim($input->name);$slug=$this->taxonomy->slug($name);$parent=$input->parentId===null?null:$this->subjects->findById($input->parentId);if($input->parentId!==null&&$parent===null)throw new \DomainException('Assunto pai nao encontrado.');if($this->subjects->findByParentAndSlug($input->parentId,$slug)!==null)throw new \DomainException('Ja existe um assunto com este nome no mesmo nivel.');$subject=new TaxonomySubject($this->uuid(),$input->parentId,$name,$slug,$input->description===null?null:trim($input->description),$parent===null?0:$parent->level+1,true);$this->subjects->save($subject);return $this->mapper->toResponse($subject);});} private function uuid():string{$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));} }
